svg.script:
(() => {
  const root = document.currentScript.ownerSVGElement;
  const ns = 'http://www.w3.org/2000/svg';
  const trigger = root.querySelector('#zf-trigger');
  const popup = root.querySelector('#zf-calendar');
  const days = root.querySelector('#zf-days');
  const cells = root.querySelector('#zf-day-cells');
  const selection = root.querySelector('#zf-selection');
  const title = root.querySelector('#zf-date-title');
  const monthTitle = root.querySelector('#zf-month-title');
  const closeButton = root.querySelector('[data-action="close"]');
  const months = ['January','February','March','April','May','June','July','August','September','October','November','December'];
  const weekdays = ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
  const date = (year, month, day) => new Date(Date.UTC(year, month, day));
  const key = value => value.toISOString().slice(0,10);
  const fromKey = value => new Date(value + 'T00:00:00Z');
  const fullDate = value => `${weekdays[value.getUTCDay()]} ${value.getUTCDate()} ${months[value.getUTCMonth()]} ${value.getUTCFullYear()}`;
  const reducedMotion = matchMedia('(prefers-reduced-motion: reduce)');
  const motion = {duration:340, easing:'cubic-bezier(.22,.8,.25,1)'};
  let renderedMonth = null;
  let monthAnimations = [];
  let ghosts = [];
  let selectionAnimation = null;
  let selected = date(2021, 1, 9);
  let displayed = date(2021, 1, 1);
  let focused = new Date(selected);
  let opened = false;

  function node(tag, attributes, text) {
    const element = document.createElementNS(ns, tag);
    Object.entries(attributes).forEach(([name, value]) => element.setAttribute(name, value));
    if (text !== undefined) element.textContent = text;
    return element;
  }

  function updateHeading() {
    const d = selected.getUTCDate();
    title.textContent = `${weekdays[selected.getUTCDay()].slice(0,3)} ${d} ${months[selected.getUTCMonth()].slice(0,3)} ${selected.getUTCFullYear()}`;
    trigger.setAttribute('aria-label', `Choose date, ${fullDate(selected)}`);
    const width = Math.min(215, title.getComputedTextLength() + 14);
    root.querySelector('.zf-trigger-hover').setAttribute('width', width);
    trigger.querySelector('.zf-focus').setAttribute('width', width);
  }

  function clearMonthMotion() {
    monthAnimations.forEach(animation => animation.cancel());
    monthAnimations = [];
    ghosts.forEach(ghost => ghost.remove());
    ghosts = [];
  }

  function ghostOf(element) {
    const ghost = element.cloneNode(true);
    ghost.removeAttribute('id');
    ghost.setAttribute('aria-hidden', 'true');
    ghost.removeAttribute('aria-live');
    ghost.style.pointerEvents = 'none';
    ghost.querySelectorAll('[id]').forEach(child => child.removeAttribute('id'));
    ghost.querySelectorAll('[tabindex]').forEach(child => child.setAttribute('tabindex', '-1'));
    return ghost;
  }

  function updateSelection(animate) {
    const selectedCell = cells.querySelector(`[data-date="${key(selected)}"]`);
    const wasVisible = selection.getAttribute('opacity') === '1';
    const previousTransform = getComputedStyle(selection).transform;
    selectionAnimation?.cancel();
    selectionAnimation = null;
    if (!selectedCell) {
      selection.setAttribute('opacity', '0');
      return;
    }
    const target = `translate(${selectedCell.dataset.highlightX}px, ${selectedCell.dataset.highlightY}px)`;
    selection.style.transform = target;
    selection.setAttribute('opacity', '1');
    if (animate && wasVisible && !reducedMotion.matches) {
      selectionAnimation = selection.animate([{transform:previousTransform}, {transform:target}], motion);
    }
  }

  function drawCalendar(focusDay = false, animateSelection = false, animateMonth = true) {
    const year = displayed.getUTCFullYear();
    const month = displayed.getUTCMonth();
    const monthIndex = year * 12 + month;
    const changedMonth = monthIndex !== renderedMonth;
    const direction = renderedMonth === null ? 0 : Math.sign(monthIndex - renderedMonth);
    const swoosh = opened && changedMonth && renderedMonth !== null && animateMonth && !reducedMotion.matches;
    let outgoingDays, outgoingLabel, oldGridStyle, oldLabelStyle;
    if (swoosh) {
      const gridStyle = getComputedStyle(days);
      const labelStyle = getComputedStyle(monthTitle);
      oldGridStyle = {transform:gridStyle.transform, opacity:gridStyle.opacity};
      oldLabelStyle = {transform:labelStyle.transform, opacity:labelStyle.opacity};
      outgoingDays = ghostOf(days);
      outgoingLabel = ghostOf(monthTitle);
      outgoingDays.querySelector('.zf-selection').style.transform = getComputedStyle(selection).transform;
    }
    if (changedMonth || !animateMonth) clearMonthMotion();
    const offset = (date(year, month, 1).getUTCDay() + 6) % 7;
    const count = date(year, month + 1, 0).getUTCDate();
    const rows = Math.max(5, Math.ceil((offset + count) / 7));
    monthTitle.textContent = `${months[month]} ${year}`;
    const bottom = 138 + rows * 28;
    root.querySelector('#zf-shell').setAttribute('d', `M126 52H329Q335 52 335 58V${bottom-6}Q335 ${bottom} 329 ${bottom}H126Q120 ${bottom} 120 ${bottom-6}V58Q120 52 126 52Z`);
    root.querySelector('#zf-grid-clip-rect').setAttribute('height', bottom - 134);
    if (changedMonth) {
      cells.replaceChildren();
      for (let index = 0; index < rows * 7; index++) {
        const value = date(year, month, index - offset + 1);
        const center = 136.5 + (index % 7) * 30;
        const y = 153 + Math.floor(index / 7) * 28;
        const button = node('g', {
          class: `zf-control zf-day${value.getUTCMonth() !== month ? ' is-outside' : ''}`,
          role:'button', tabindex:'-1', 'aria-label':fullDate(value),
          'data-date':key(value), 'data-action':'select',
          'data-highlight-x':center-10, 'data-highlight-y':y-14
        });
        button.append(
          node('rect', {x:center-15, y:y-18, width:30, height:28, fill:'transparent'}),
          node('rect', {class:'zf-day-fill', x:center-10, y:y-14, width:20, height:19, rx:4}),
          node('text', {x:center, y, 'text-anchor':'middle', 'font-size':12, 'aria-hidden':'true'}, value.getUTCDate()),
          node('rect', {class:'zf-focus', x:center-12, y:y-16, width:24, height:24, rx:5})
        );
        cells.append(button);
      }
    }
    cells.querySelectorAll('[data-date]').forEach(button => {
      const chosen = button.dataset.date === key(selected);
      button.classList.toggle('is-selected', chosen);
      button.setAttribute('aria-pressed', String(chosen));
      button.setAttribute('tabindex', opened && button.dataset.date === key(focused) ? '0' : '-1');
    });
    updateSelection(animateSelection && !changedMonth);
    renderedMonth = monthIndex;
    if (swoosh) {
      days.parentNode.insertBefore(outgoingDays, days);
      monthTitle.parentNode.insertBefore(outgoingLabel, monthTitle);
      ghosts = [outgoingDays, outgoingLabel];
      const animations = [
        outgoingDays.animate([oldGridStyle, {transform:`translateX(${-direction * 215}px)`, opacity:0}], motion),
        days.animate([{transform:`translateX(${direction * 215}px)`, opacity:.35}, {transform:'translateX(0)', opacity:1}], motion),
        outgoingLabel.animate([oldLabelStyle, {transform:`translateX(${-direction * 40}px)`, opacity:0}], motion),
        monthTitle.animate([{transform:`translateX(${direction * 40}px)`, opacity:0}, {transform:'translateX(0)', opacity:1}], motion)
      ];
      monthAnimations = animations;
      Promise.allSettled(animations.map(animation => animation.finished)).then(() => {
        outgoingDays.remove();
        outgoingLabel.remove();
        if (monthAnimations === animations) { monthAnimations = []; ghosts = []; }
      });
    }
    if (focusDay && opened) cells.querySelector(`[data-date="${key(focused)}"]`)?.focus();
  }

  function setOpen(value, restoreFocus = false, focusDay = value) {
    opened = value;
    if (opened) {
      displayed = date(selected.getUTCFullYear(), selected.getUTCMonth(), 1);
      focused = new Date(selected);
    }
    root.classList.toggle('is-open', opened);
    trigger.setAttribute('aria-expanded', String(opened));
    popup.setAttribute('aria-hidden', String(!opened));
    closeButton.setAttribute('aria-hidden', String(!opened));
    closeButton.setAttribute('tabindex', opened ? '0' : '-1');
    popup.querySelectorAll('.zf-month-button').forEach(button => button.setAttribute('tabindex', opened ? '0' : '-1'));
    drawCalendar(focusDay, false, false);
    if (!opened && restoreFocus) trigger.focus();
  }

  function moveMonth(delta, focusDay = false) {
    displayed = date(displayed.getUTCFullYear(), displayed.getUTCMonth() + delta, 1);
    const lastDay = date(displayed.getUTCFullYear(), displayed.getUTCMonth() + 1, 0).getUTCDate();
    focused = date(displayed.getUTCFullYear(), displayed.getUTCMonth(), Math.min(focused.getUTCDate(), lastDay));
    drawCalendar(focusDay);
  }

  function activate(button) {
    const action = button.getAttribute('data-action');
    if (action === 'toggle') setOpen(!opened, opened);
    if (action === 'close') setOpen(false, true);
    if (action === 'previous') moveMonth(-1);
    if (action === 'next') moveMonth(1);
    if (action === 'select') {
      selected = fromKey(button.getAttribute('data-date'));
      focused = new Date(selected);
      displayed = date(selected.getUTCFullYear(), selected.getUTCMonth(), 1);
      updateHeading();
      drawCalendar(true, true);
      root.dispatchEvent(new CustomEvent('datechange', {bubbles:true, detail:{date:key(selected)}}));
    }
  }

  trigger.addEventListener('pointerenter', () => root.classList.add('is-trigger-hovered'));
  trigger.addEventListener('pointerleave', () => root.classList.remove('is-trigger-hovered'));
  reducedMotion.addEventListener('change', () => {
    if (reducedMotion.matches) { clearMonthMotion(); selectionAnimation?.cancel(); }
  });
  root.addEventListener('click', event => {
    const button = event.target.closest('[data-action]');
    if (button && root.contains(button)) activate(button);
    else if (opened && !popup.contains(event.target)) setOpen(false);
  });
  document.addEventListener('click', event => {
    if (opened && !event.composedPath().includes(root)) setOpen(false);
  });
  root.addEventListener('keydown', event => {
    if (event.key === 'Escape' && opened) {
      event.preventDefault();
      setOpen(false, true);
      return;
    }
    const button = event.target.closest('[data-action]');
    if (!button) return;
    if (event.key === 'Enter' || event.key === ' ') {
      event.preventDefault();
      activate(button);
      return;
    }
    if (button === trigger && ['ArrowDown','ArrowUp'].includes(event.key)) {
      event.preventDefault();
      setOpen(true);
      return;
    }
    if (!opened || !button.hasAttribute('data-date')) return;
    focused = fromKey(button.getAttribute('data-date'));
    if (event.key === 'PageUp' || event.key === 'PageDown') {
      event.preventDefault();
      moveMonth((event.key === 'PageUp' ? -1 : 1) * (event.shiftKey ? 12 : 1), true);
      return;
    }
    const weekday = (focused.getUTCDay() + 6) % 7;
    const movement = {ArrowLeft:-1, ArrowRight:1, ArrowUp:-7, ArrowDown:7, Home:-weekday, End:6-weekday}[event.key];
    if (movement === undefined) return;
    event.preventDefault();
    focused = date(focused.getUTCFullYear(), focused.getUTCMonth(), focused.getUTCDate() + movement);
    displayed = date(focused.getUTCFullYear(), focused.getUTCMonth(), 1);
    drawCalendar(true);
  });
  document.addEventListener('focusin', event => {
    if (opened && !root.contains(event.target)) setOpen(false);
  });
  root.addEventListener('zf-reset', () => {
    selected = date(2021, 1, 9);
    displayed = date(2021, 1, 1);
    focused = new Date(selected);
    updateHeading();
    setOpen(false);
  });
  updateHeading();
  if (location.hash === '#open') setOpen(true, false, false);
  else drawCalendar();
  document.fonts?.ready.then(() => { updateHeading(); drawCalendar(); });
})();
